<script setup lang="ts">
import type { UvStatTone,UvStatTrendDirection } from './stat.types'
interface Props { label:string; value:string|number; description?:string; trend?:string|number; trendLabel?:string; trendDirection?:UvStatTrendDirection; tone?:UvStatTone; loading?:boolean }
withDefaults(defineProps<Props>(),{description:'',trend:undefined,trendLabel:'',trendDirection:'neutral',tone:'neutral',loading:false})
</script>
<template><article class="uv-stat" :class="`uv-stat--${tone}`" :aria-busy="loading||undefined"><span class="uv-stat__label">{{ label }}</span><div v-if="loading" class="uv-stat__skeleton" role="status" aria-label="Loading statistic"></div><strong v-else class="uv-stat__value"><slot name="value">{{ value }}</slot></strong><div v-if="trend!==undefined && !loading" class="uv-stat__trend" :class="`uv-stat__trend--${trendDirection}`"><span aria-hidden="true">{{ trendDirection==='up'?'↑':trendDirection==='down'?'↓':'→' }}</span><span>{{ trend }}</span><span v-if="trendLabel" class="uv-stat__trend-label">{{ trendLabel }}</span></div><p v-if="description" class="uv-stat__description">{{ description }}</p><slot /></article></template>
<style>.uv-stat{display:grid;gap:.35rem;padding:1rem;border:1px solid var(--uv-color-border,#cbd5e1);border-radius:var(--uv-radius-md,.625rem);background:#fff;font:inherit;color:#0f172a}.uv-stat__label{color:#64748b;font-size:.875rem}.uv-stat__value{font-size:1.8rem;line-height:1.1}.uv-stat__trend{display:flex;gap:.3rem;align-items:center;font-size:.85rem}.uv-stat__trend--up{color:#15803d}.uv-stat__trend--down{color:#b91c1c}.uv-stat__trend--neutral{color:#64748b}.uv-stat__trend-label{color:#64748b}.uv-stat__description{margin:.15rem 0 0;color:#64748b}.uv-stat--primary{border-color:#93c5fd}.uv-stat--success{border-color:#86efac}.uv-stat--warning{border-color:#fde68a}.uv-stat--danger{border-color:#fca5a5}.uv-stat__skeleton{width:55%;height:1.8rem;border-radius:.35rem;background:linear-gradient(90deg,#e2e8f0,#f8fafc,#e2e8f0);background-size:200% 100%;animation:uv-stat-pulse 1.4s linear infinite}@keyframes uv-stat-pulse{to{background-position:-200% 0}}@media(prefers-reduced-motion:reduce){.uv-stat__skeleton{animation:none}}</style>
